import {createGame,step,tap,change,isInhale,rhythmInfo,rockInfo,handInfo,resetInput as clearEngineInput,RHYTHM,HAND,SOURCES,PHASES,clamp,sourceAt,getHint} from './engine.js';
import {BabyInput} from './input.js';
import {createAudio} from './audio.js';
import {createRunTimer,createLeaderboard,createFastestStore,shareGoodnight,followAuthor,getFollowStatus} from './platform.js';
const $=id=>document.getElementById(id),canvas=$('scene'),ctx=canvas.getContext('2d'),W=390,H=530;
const track=$('rhythm-track'),tc=track.getContext('2d');
const timer=createRunTimer(),leaderboard=createLeaderboard(),fastest=createFastestStore(),audio=createAudio();
let game=createGame(),playing=false,paused=false,last=0,keys=new Set(),lastPhase='',touchBalance=0,light=.1;
let tapGlow=0,tapResult='',pose=0,music=true,allSound=true,completedRun=null,rankingResult=null,runSerial=0,resultVisible=false,followed=false,rankOpenedWhilePaused=false,rankPending=false,rankRequest=0,localSaveError='';
const input={down:false,x:0,y:0,dx:0,vx:0,id:null,auto:false,dragged:false};let canvasInput=null,gestureInput=null,rhythmInput=null;
function releaseInputs(clearEngine=true){[canvasInput,gestureInput,rhythmInput].forEach(h=>{if(h)h.cancel(false)});input.down=false;input.id=null;input.dx=0;input.vx=0;input.auto=false;input.dragged=false;keys.clear();if(clearEngine)clearEngineInput(game)}
function resizeTrack(){const dpr=Math.min(window.devicePixelRatio||1,2),width=track.clientWidth||390;if(track.width!==Math.round(width*dpr)||track.height!==112*dpr){track.width=Math.round(width*dpr);track.height=112*dpr;tc.setTransform(dpr,0,0,dpr,0,0)}}
function resize(){const dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);const area=Math.min(422,Math.max(280,(window.innerWidth||440)-18)),available=Math.max(310,(window.innerHeight||850)-280);canvas.style.width=Math.min(area,available*W/H)+'px';resizeTrack()}resize();window.addEventListener('resize',resize);
function safeFocus(el){try{el.focus({preventScroll:true});}catch{try{el.focus()}catch{}}}
function unlockAudio(){audio.unlock();audio.setEnabled(allSound);audio.setMusic(music)}
function setPaused(value){timer.setPaused(value);paused=value;audio.setPaused(value||document.hidden);last=0;releaseInputs();}
function start(practice){runSerial++;rankRequest++;rankPending=false;localSaveError='';$('local-save-status').textContent='';$('share').disabled=false;$('follow').disabled=followed;game=createGame();playing=true;completedRun=null;rankingResult=null;resultVisible=false;lastPhase='';pose=0;touchBalance=0;tapGlow=0;releaseInputs();timer.start(!!practice);setPaused(false);unlockAudio();['intro','help-overlay','ranking-overlay','reward-overlay','lights-overlay'].forEach(id=>$(id).classList.add('hidden'));$('shell').classList.remove('reward-open');$('result-status').textContent='';$('rank-submit-status').textContent='';$('scene').dataset.practice=String(!!practice);if(practice){change(game,practice);game.sleep=85;game.lower=['leg','head','settle','sleeping'].includes(practice)?1:0;if(practice==='head')game.leg=1;pose=game.lower;}safeFocus(canvas);updateUI();}
BabyInput.button($('start'),()=>start(false));BabyInput.button($('restart'),()=>start(false));BabyInput.button($('result-restart'),()=>start(false));
document.querySelectorAll('[data-practice]').forEach(b=>BabyInput.button(b,()=>start(b.dataset.practice)));
BabyInput.button($('help'),()=>{setPaused(true);$('help-overlay').classList.remove('hidden');updateUI();safeFocus($('resume'))});
BabyInput.button($('resume'),()=>{$('help-overlay').classList.add('hidden');if(!resultVisible)setPaused(false);updateUI();if(playing)safeFocus(canvas)});
BabyInput.button($('music'),()=>{music=!music;unlockAudio();$('music').textContent=music?'音乐 开':'音乐 关';$('music').setAttribute('aria-pressed',String(music))});
BabyInput.button($('all-sound'),()=>{allSound=!allSound;unlockAudio();$('all-sound').textContent=allSound?'全部声音 开':'全部声音 关';$('all-sound').setAttribute('aria-pressed',String(allSound))});
function renderRestriction(state){if(state&&state.hideEntry){$('ranking').classList.add('hidden');$('ranking-unavailable').classList.remove('hidden');$('ranking-unavailable').textContent='榜单未授权';$('ranking-unavailable').title=state.message;}$('rank-submit-status').textContent=state&&state.message||'';}
function elapsedText(ms){return Number.isFinite(ms)?(ms/1000).toFixed(2)+' 秒':'—';}
async function showRanking(){if(rankPending||!$('ranking-overlay').classList.contains('hidden'))return;const request=++rankRequest;rankPending=true;rankOpenedWhilePaused=paused;setPaused(true);updateUI();$('ranking-overlay').classList.remove('hidden');$('rank-status').textContent='读取中…';$('rank-list').textContent='';$('my-rank').textContent='';$('local-fastest').textContent='';const local=await fastest.load();if(request!==rankRequest)return;$('local-fastest').textContent=local.status==='error'?local.message:local.bestElapsedMs?'本机最快 '+elapsedText(local.bestElapsedMs):'本机尚无成绩';const state=await leaderboard.load('all');if(request!==rankRequest)return;rankPending=false;if(state.status!=='ready'){$('rank-status').textContent=state.message;renderRestriction(state);return;}$('rank-status').textContent=state.empty?'还没有有效成绩':'哄睡越快，排名越前';state.rows.forEach(row=>{const li=document.createElement('li'),name=document.createElement('span'),time=document.createElement('b');name.textContent=row.rank+'. '+row.nickname;time.textContent=elapsedText(row.elapsedMs);li.appendChild(name);li.appendChild(time);$('rank-list').appendChild(li)});const mine=state.mine;$('my-rank').textContent=mine.status==='EXACT'?'我的排名 '+mine.rank+' · '+elapsedText(mine.elapsedMs):mine.status==='OVER_LIMIT'?'我的排名 500+':mine.status==='NO_SCORE'?'本期尚无成绩':'本期未参与排行';}
BabyInput.button($('ranking'),showRanking);BabyInput.button($('close-ranking'),()=>{rankRequest++;rankPending=false;$('ranking-overlay').classList.add('hidden');if(!rankOpenedWhilePaused&&!resultVisible)setPaused(false);updateUI()});
function finishTiming(){if(completedRun)return;completedRun=timer.finishSleeping();const serial=runSerial;fastest.record(completedRun).then(state=>{if(serial!==runSerial)return;localSaveError=state.status==='error'?state.message:'';$('local-save-status').textContent=localSaveError;});$('rank-submit-status').textContent=completedRun.practice?'练习局不计排行':completedRun.eligible?'正在记录成绩…':'计时异常，本局不计排行';leaderboard.submitRun(completedRun).then(state=>{if(serial!==runSerial)return;rankingResult=state;renderRestriction(state);updateUI()});}
function showReward(){if(resultVisible)return;resultVisible=true;setPaused(true);$('shell').classList.add('reward-open');$('reward-overlay').classList.remove('hidden');$('result-time').textContent=completedRun?elapsedText(completedRun.elapsedMs):'—';$('result-status').textContent='';const serial=runSerial;getFollowStatus().then(state=>{if(serial!==runSerial||!resultVisible)return;if(state.followStatus===1||state.followStatus===2){followed=true;$('follow').textContent='已关注';$('follow').disabled=true;}});}
function makeShareCard(){const c=document.createElement('canvas');c.width=750;c.height=1000;const g=c.getContext('2d');g.fillStyle='#172425';g.fillRect(0,0,750,1000);g.drawImage(canvas,108,135,534,726);g.fillStyle='#dccb91';g.textAlign='center';g.font='36px sans-serif';g.fillText('☾ 哄睡专家 · 守住一小觉',375,78);g.fillStyle='rgba(18,32,31,.94)';g.fillRect(108,750,534,111);g.font='28px sans-serif';g.fillStyle='#dccb91';g.fillText('宝宝和妈妈，都睡着了。',375,795);g.font='24px sans-serif';g.fillText('哄睡用时 '+(completedRun?elapsedText(completedRun.elapsedMs):'—'),375,834);g.font='32px sans-serif';g.fillText('晚安，小祖宗。',375,941);return c.toDataURL('image/png');}
BabyInput.button($('share'),async()=>{const serial=runSerial;$('share').disabled=true;$('result-status').textContent='';try{const state=await shareGoodnight(makeShareCard());if(serial!==runSerial)return;$('result-status').textContent=state.status==='publish_flow_completed'?'':state.message;}catch{if(serial===runSerial)$('result-status').textContent='分享卡生成失败，请重试。'}finally{if(serial===runSerial)$('share').disabled=false;}});
BabyInput.button($('follow'),async()=>{if(followed)return;const serial=runSerial;$('follow').disabled=true;const state=await followAuthor();if(serial!==runSerial)return;if(state.followStatus===1||state.followStatus===2){followed=true;$('follow').textContent='已关注';$('result-status').textContent='';}else{$('result-status').textContent=state.message;$('follow').disabled=false;}});
BabyInput.button($('lights-out'),()=>{audio.setPaused(true);$('reward-overlay').classList.add('hidden');$('lights-overlay').classList.remove('hidden')});BabyInput.button($('lights-back'),()=>{$('lights-overlay').classList.add('hidden');$('reward-overlay').classList.remove('hidden')});
window.addEventListener('blur',()=>releaseInputs());document.addEventListener('visibilitychange',()=>{timer.setHidden(document.hidden);last=0;releaseInputs();if(document.hidden){audio.setPaused(true);if(playing&&!resultVisible){setPaused(true);$('help-overlay').classList.remove('hidden');}}else audio.setPaused(paused);updateUI()});
function pos(p){const r=canvas.getBoundingClientRect();return{x:(p.clientX-r.left)*W/r.width,y:(p.clientY-r.top)*H/r.height}}
function targetAt(p){return sourceAt(p.x,p.y,game.events.filter(e=>e.status==='warning').map(e=>e.id))}
function doTap(target='baby'){if(!playing||paused)return;unlockAudio();const r=tap(game,target);tapResult=r;tapGlow=.5;audio.tap(r);updateUI();}
const rhythmPad=$('rhythm-pad');let tapStarted=0,tapPhase='';function tapStart(){tapStarted=Date.now();tapPhase=game.phase;if(game.phase!=='rock'&&RHYTHM[game.phase])doTap();}
function tapEnd(p,e,g){if(game.phase==='rock'&&tapPhase==='rock'&&Date.now()-tapStarted<=600&&g.maxDistance<=18&&Math.hypot(p.clientX-g.start.clientX,p.clientY-g.start.clientY)<=18)doTap();}
rhythmInput=BabyInput.bind(rhythmPad,{start:tapStart,end:tapEnd,cancel:()=>releaseInputs(),click:()=>{if(game.phase==='rock'||RHYTHM[game.phase])doTap()}});
function beginGesture(p,auto){if(!playing||paused||input.down)return;unlockAudio();Object.assign(input,{down:true,id:1,x:p.clientX,y:p.clientY,dx:0,vx:0,auto:!!auto,dragged:false})}
function moveGesture(p){if(!input.down||!playing||paused)return;const dx=(p.clientX-input.x)*390/canvas.getBoundingClientRect().width;input.dx+=dx;if(Math.abs(dx)>.5)input.dragged=true;if(game.phase==='lower')touchBalance=clamp(touchBalance+dx/110,-1,1);input.x=p.clientX;input.y=p.clientY}
gestureInput=BabyInput.bind($('gesture-pad'),{start:p=>beginGesture(p,true),move:moveGesture,end:()=>releaseInputs(false),cancel:()=>releaseInputs()});
canvasInput=BabyInput.bind(canvas,{start:p=>{if(!playing||paused)return;if(['lower','leg','head'].includes(game.phase))beginGesture(p,false);else if(game.phase==='sleeping')doTap(targetAt(pos(p)));else tapStart();},move:moveGesture,end:(p,e,g)=>{tapEnd(p,e,g);releaseInputs(false)},cancel:()=>releaseInputs(),click:p=>{if(game.phase==='sleeping')doTap(targetAt(pos(p)));else if(game.phase==='rock'||RHYTHM[game.phase])doTap();}});
canvas.addEventListener('keydown',e=>{if(!playing||paused)return;if(['ArrowLeft','ArrowRight',' '].includes(e.key)){e.preventDefault();keys.add(e.key);if(e.key===' '&&!e.repeat&&(game.phase==='rock'||RHYTHM[game.phase]))doTap()}if(game.phase==='sleeping'&&/^[1-8]$/.test(e.key)&&!e.repeat)doTap(SOURCES[Number(e.key)-1].id)});
window.addEventListener('keyup',e=>{keys.delete(e.key);if(!keys.size&&input.id===null)releaseInputs(false)});
function updateUI(){const r=rhythmInfo(game),rock=game.phase==='rock',hi=handInfo(game),rhythm=playing&&(rock||!!r),gesture=playing&&['lower','leg','head'].includes(game.phase),active=(rhythm||gesture)&&!paused;$('controls').classList.toggle('active',active);$('controls').classList.toggle('rock-mode',rock);$('rhythm-ui').classList.toggle('hidden',!rhythm);if(rhythm)resizeTrack();$('gesture-ui').classList.toggle('hidden',!gesture);rhythmPad.disabled=!rhythm||paused;rhythmPad.classList.toggle('ready',rock?rockInfo(game).canTap:!!r&&r.distance<.14&&r.beat!==game.lastBeat);$('gesture-pad').disabled=!gesture||paused;$('gesture-pad').classList.toggle('ready',!!hi&&hi.open);$('pad-label').textContent=rock?'顶点轻点':game.phase==='pat'?'轻拍':'再轻拍';
 const names={rock:'轻摇',pat:'轻拍',lower:'放下',leg:'抽腿下手',head:'抽头下手',settle:'轻拍',sleeping:'深睡',awake:'醒了'};$('phase-label').textContent=names[game.phase];$('stage-dots').innerHTML=PHASES.map((p,i)=>`<i class="${p===game.phase?'active':i<PHASES.indexOf(game.phase)?'done':''}"></i>`).join('');const timing=timer.getState();$('rest-label').textContent=playing?(completedRun?'哄睡 '+elapsedText(completedRun.elapsedMs):elapsedText(timing?timing.elapsedMs:0)):'';
 canvas.dataset.phase=game.phase;canvas.dataset.progress=game.progress.toFixed(3);canvas.dataset.lower=game.lower.toFixed(3);canvas.dataset.hand=(hi?game[game.phase]:0).toFixed(3);canvas.dataset.rest=game.rest.toFixed(2);canvas.dataset.cleared=game.cleared;canvas.dataset.paused=String(paused);$('shell').dataset.phase=game.phase;
 const lower=game.phase==='lower';$('hint').textContent=lower?'按住，左右微调保持平衡':hi?(hi.open?'呼气窗口 · 现在抽':isInhale(game)?'吸气 · 松开停稳':'等下一口气'):'';$('gesture-icon').textContent=lower?'↔':game.phase==='leg'?'→':'←';$('gesture-label').textContent=lower?'按住 · 调平':hi&&hi.open?'按住 · 慢抽':'松开 · 等待';$('gesture-pad').setAttribute('aria-label',lower?'按住并左右拖动保持平衡':game.phase==='leg'?'呼气短窗口按住慢抽腿下的手':'呼气短窗口按住慢抽头下的手');$('hand-progress').textContent=hi?Math.round(game[game.phase]*100)+'%':'';
 $('quiet-hint').classList.toggle('hidden',!playing||rhythm||gesture);$('quiet-hint').textContent=game.phase==='sleeping'?'守睡 '+timeFormat(game.rest)+' / 01:00':game.phase==='awake'?'再抱稳一点':'';$('feedback').textContent=playing?(game.feedbackTime>0?game.feedback:game.noticeTime>0?game.notice:getHint(game)):'';
 if(game.phase!==lastPhase){lastPhase=game.phase;releaseInputs(false);if(['lower','leg','head'].includes(game.phase))clearEngineInput(game);if(game.phase==='lower')touchBalance=0;if(game.phase==='sleeping')finishTiming();}if(game.complete)showReward();
}

function round(x,y,w,h,r,fill,stroke){ctx.beginPath();r=Math.min(r,Math.max(0,w)/2,Math.max(0,h)/2);ctx.moveTo(x+r,y);ctx.lineTo(x+w-r,y);ctx.quadraticCurveTo(x+w,y,x+w,y+r);ctx.lineTo(x+w,y+h-r);ctx.quadraticCurveTo(x+w,y+h,x+w-r,y+h);ctx.lineTo(x+r,y+h);ctx.quadraticCurveTo(x,y+h,x,y+h-r);ctx.lineTo(x,y+r);ctx.quadraticCurveTo(x,y,x+r,y);ctx.closePath();if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1.3;ctx.stroke()}}
function ellipse(x,y,rx,ry,fill){ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fillStyle=fill;ctx.fill()}
function line(x1,y1,x2,y2,color,width=2){ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.lineCap='round';ctx.stroke()}
function label(text,x,y,size=11,color='#a8aa94',align='center'){ctx.fillStyle=color;ctx.font=`${size}px -apple-system, BlinkMacSystemFont, "PingFang SC", sans-serif`;ctx.textAlign=align;ctx.fillText(text,x,y)}
function arc(x,y,r,a,b,color,width=2){ctx.beginPath();ctx.arc(x,y,r,a,b);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.lineCap='round';ctx.stroke()}
function poly(points,fill){ctx.beginPath();points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();ctx.fillStyle=fill;ctx.fill()}
function timeFormat(s){return `${Math.floor(s/60).toString().padStart(2,'0')}:${Math.floor(s%60).toString().padStart(2,'0')}`}
function facetedHead(x,y,r){const points=[];for(let i=0;i<12;i++){const a=-Math.PI/2+i*Math.PI/6;points.push([x+Math.cos(a)*r,y+Math.sin(a)*r])}poly(points,'#f2bc94');for(let i=0;i<12;i++){const shades=['#f8c9a4','#f8c9a4','#f0b88f','#e9ad83','#dca077','#e4a97e','#e8ad83','#edb58c','#f3bd94','#f8c7a0','#fbd0ad','#fbd0ad'];poly([points[i],points[(i+1)%12],[x,y+3]],shades[i]);}poly([[x-r*.72,y-r*.4],[x+r*.72,y-r*.4],[x+r*.78,y+r*.3],[x-r*.78,y+r*.3]],'#f5c19a')}
function mom(){const x=47,y=47;ellipse(x+12,y-24,10,10,'#51453e');poly([[x-24,y-6],[x-20,y-24],[x-6,y-31],[x+17,y-26],[x+25,y-5],[x+18,y+18],[x-20,y+17]],'#493e39');facetedHead(x,y+3,21);poly([[x-22,y-2],[x-18,y-18],[x-5,y-26],[x+15,y-18],[x+22,y-2],[x+5,y-10],[x-7,y-6]],'#594940');ctx.globalAlpha=.12+(1-game.mamaRest)*.7;ellipse(x-7,y+9,7.5,6,'#66545b');ellipse(x+10,y+9,7.5,6,'#66545b');ctx.globalAlpha=1;ellipse(x-7,y+4,7,6,'#fff6eb');ellipse(x+10,y+4,7,6,'#fff6eb');if(game.phase==='sleeping'){line(x-11,y+4,x-3,y+4,'#423d32',2);line(x+6,y+4,x+14,y+4,'#423d32',2)}else{ellipse(x-5,y+5,2,2.3,'#332d29');ellipse(x+12,y+5,2,2.3,'#332d29')}line(x-2,y+18,x+4,y+18,'#463b31',2);}
function room(){ctx.fillStyle='#1b202c';ctx.fillRect(0,0,W,H);poly([[0,170],[390,170],[390,530],[0,530]],'#292a2b');line(0,172,390,172,'#373537',2);for(let i=0;i<7;i++)line(0,240+i*48,390,225+i*48,'#2d2e2f',1);const grad=ctx.createRadialGradient(194,280,30,194,280,245);grad.addColorStop(0,'rgba(227,185,111,.19)');grad.addColorStop(.55,'rgba(227,185,111,.09)');grad.addColorStop(1,'rgba(227,185,111,0)');ctx.fillStyle=grad;ctx.fillRect(0,0,W,H);ctx.globalAlpha=.08;poly([[193,0],[52,470],[337,470]],'#f4d28b');ctx.globalAlpha=1;round(162,-6,65,14,4,'#867759');ellipse(195,7,26,3,'#dfbd78');ellipse(194,490,122,21,'#1d2025');round(24,397,19,8,3,'#596455');round(33,403,19,8,3,'#756047');ellipse(72,482,13,9,'#806859');line(60,478,83,486,'#aa9278',3);ellipse(49,348,12,5,'#5c6962');}
function bed(){round(82,134,227,338,20,'#887052');round(93,145,205,310,16,'#b8aa85','#baa77c');round(101,152,189,291,11,'#bcb694');for(let i=0;i<8;i++){line(89,159+i*40,89,180+i*40,'#b49768',5);line(302,159+i*40,302,180+i*40,'#b49768',5)}for(let i=0;i<6;i++)line(104+i*35,447,104+i*35,475,'#b29668',4);line(89,472,302,472,'#92744f',6);line(87,136,87,455,'#a88960',7);line(304,136,304,455,'#a88960',7);}
function props(){for(const s of SOURCES){const {x,y,id}=s,e=game.events.find(e=>e.id===id&&e.status==='warning'),pulse=e?Math.sin(game.time*8):0;ctx.save();ctx.translate(x,y);ctx.scale(.76,.76);if(id==='phone'){round(-15,-23,30,48,5,'#4e6465');round(-11,-18,22,34,3,e?'#d8c27d':'#3c4e52');ellipse(0,20,2,2,'#899895');if(e){arc(0,-2,6,.4,2.6,'#354b45',2);}}else if(id==='ledge'){round(-27,10,54,8,3,'#8b6c4b');line(-21,18,-21,34,'#70583f',4);line(21,18,21,34,'#70583f',4);const slide=e?(1-e.left/e.lead)*22:0;ctx.save();ctx.translate(slide,-3);ctx.rotate(e?(1-e.left/e.lead)*.28:0);ellipse(0,0,14,11,'#c38f7e');ellipse(12,0,7,5,'#d5a18c');ellipse(14,-1,1,1.2,'#6d5144');ellipse(16,-1,1,1.2,'#6d5144');poly([[-8,-8],[-6,-17],[1,-9]],'#bd8979');ellipse(5,-4,1.7,2,'#403d33');line(-8,8,-8,13,'#a57266',4);line(6,8,6,13,'#a57266',4);arc(-15,0,5,1.8,5.5,'#bf8c79',2);ctx.restore();if(e){line(27,20,27,31,'#caa972',1);label('↓',27,44,13,'#caa972');}}else if(id==='bell'){const roll=e?(1-e.left/e.lead)*22:0;ctx.save();ctx.translate(-10+roll,Math.sin(roll*.22)*-2);ctx.rotate(roll*.075);ellipse(0,0,13,14,'#b49a5c');arc(0,-15,4,0,Math.PI*2,'#d5bb74',2);line(-9,5,9,5,'#62533d',2);ellipse(0,7,2.5,3,'#62533d');arc(-4,-3,5,3.4,4.7,'#e0c783',2);ctx.restore();if(e){line(-30,-7,-23,-7,'#9f976e',1.4);line(-31,1,-20,1,'#9f976e',1.4);}}else if(id==='door'){round(-22,-38,44,77,3,'#544b40','#817056');round(-17,-31,34,64,2,'#645744');line(8,4,14,4+pulse*3,'#c1aa73',4);}else if(id==='cat'){round(-28,17,55,10,3,'#615744');ctx.save();ctx.translate(17,8);ctx.rotate(e?pulse*.13:0);round(-7,-15,14,20,3,'#93a1a1');arc(8,-5,5,-1.4,1.4,'#93a1a1',3);ctx.restore();ellipse(-13,7,13,15,'#9b8d79');ellipse(-16,-9,13,12,'#ac9b81');poly([[-28,-15],[-26,-29],[-16,-18]],'#ac9b81');poly([[-13,-18],[-4,-28],[-3,-11]],'#ac9b81');ellipse(-21,-8,2,3,'#332f2c');ellipse(-11,-8,2,3,'#332f2c');line(-4,6,9+(e?pulse*3:0),-1,'#ac9b81',5);arc(-29,15,10,2,4.8,'#9b8d79',5);}else if(id==='clock'){ellipse(0,2,19,18,'#8b8064');ellipse(0,2,14,14,'#c1b28d');line(0,2,0,-8,'#4f534b',2);line(0,2,8,pulse*5+2,'#4f534b',2);arc(-12,-16,7,3.5,6.1,'#9b8b67',4);arc(12,-16,7,3.5,6.1,'#9b8b67',4);}else if(id==='toy'){round(-23,-10,46,22,7,'#9b7957');round(-12,-20,25,19,7,'#a88f66');ellipse(-14,14,7,7,'#4d5555');ellipse(15,14,7,7,'#4d5555');ellipse(18,-5,4,4,e?'#e7cd78':'#a7966b');}else if(id==='window'){round(-23,-28,46,57,3,'#83755d');round(-18,-23,36,47,2,'#343f57');line(0,-22,0,23,'#8e8064',3);line(-17,0,17,0+pulse*2,'#8e8064',3);arc(10,-11,6,.8,4.8,'#bebd94',3);}ctx.restore();}}

function arm(fromX,fromY,toX,toY,side,pull=0,pat=0){ctx.save();ctx.globalAlpha=1-pull*.85;const d=side*pull*145;ctx.beginPath();ctx.moveTo(fromX+d,fromY+40);ctx.quadraticCurveTo(fromX+d-side*12,fromY-50,toX+d,toY+pat);ctx.lineWidth=34;ctx.strokeStyle='#c49a7d';ctx.lineCap='round';ctx.stroke();ctx.beginPath();ctx.moveTo(fromX+d,fromY+25);ctx.lineTo(fromX+d-side*6,fromY-19);ctx.lineWidth=48;ctx.strokeStyle='#4e6969';ctx.stroke();ctx.save();ctx.translate(toX+d,toY+pat);ctx.rotate(side*.45);ellipse(0,0,24,17,'#e0b28d');for(let i=0;i<3;i++)line(-13+i*7,-5,-12+i*7,8,'#c28d6d',1);ctx.restore();ctx.restore()}
function baby(){const bedPhase=['leg','head','settle','sleeping'].includes(game.phase);const target=bedPhase?1:game.phase==='lower'?game.lower:0;pose+=(target-pose)*.08;const sway=game.phase==='rock'?rockInfo(game).angle*22:game.phase==='pat'?Math.sin(game.phaseTime*Math.PI*2/RHYTHM.pat.period)*2.7:0;
 const x=111+(195-111)*pose+sway,y=290-51*pose,angle=-1.25*(1-pose)+(game.phase==='rock'?rockInfo(game).angle*.22:game.phase==='lower'?game.balance*.12:0),scale=1.24-.24*pose;
 const xy=(lx,ly)=>({x:x+(lx*Math.cos(angle)-ly*Math.sin(angle))*scale,y:y+(lx*Math.sin(angle)+ly*Math.cos(angle))*scale});const head=xy(0,20),bum=xy(2,93);
 if(pose<.95){ctx.save();ctx.globalAlpha=(1-pose)*.8;ellipse(58,522,87,65,'#3b5255');ellipse(332,522,87,65,'#3b5255');ctx.restore()}
 const handsVisible=!['settle','sleeping'].includes(game.phase);if(handsVisible){arm(40,490,head.x-9,head.y+14,-1,game.head);arm(351,490,bum.x+10,bum.y+15,1,game.leg,game.phase==='pat'?-game.hit*9:0)}
 ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.scale(scale,scale);const breathing=1+Math.sin((handInfo(game)?game.phaseTime:game.time)*2*Math.PI/3.8)*.008;ctx.scale(1,breathing);
 ellipse(2,81,31,46,'#c8a45b');round(-26,37,52,82,23,'#efd17d');round(-15,45,29,67,13,'#f4d88d');line(-20,111,-24,133,'#dfbe70',19);line(17,111,21,132,'#e8c77a',19);ellipse(-25,138,10,7,'#e6b48e');ellipse(22,138,10,7,'#edbd98');line(-25,51,-39,77,'#e2be73',16);line(25,51,35,75,'#eacb81',16);ellipse(-39,80,7,7,'#edbd98');ellipse(35,78,7,7,'#edbd98');
 facetedHead(0,0,39);const open=game.phase==='awake'?1:clamp(Math.max(1-game.sleep/84,game.arousal/100),0,1);if(open>.06){const h=2+open*11;ellipse(-14,-1,12,h,'#fff9ec');ellipse(14,-1,12,h,'#fff9ec');ellipse(-12,-3,5,Math.min(h,6),'#2e3030');ellipse(12,-3,5,Math.min(h,6),'#2e3030');ellipse(-10,-5,1.8,1.8,'#fff');ellipse(14,-5,1.8,1.8,'#fff');arc(-13,-13,9,3.6,5.8,'#6a4c39',2.4);arc(13,-13,9,3.6,5.8,'#6a4c39',2.4)}else{arc(-14,-3,8,.2,Math.PI-.2,'#654938',2.4);arc(14,-3,8,.2,Math.PI-.2,'#654938',2.4)}ellipse(-24,14,7,3,'#dd9680');ellipse(24,14,7,3,'#dd9680');if(game.phase==='awake')ellipse(0,22,11,13,'#49332d');else if(game.arousal>60)ellipse(0,21,4,6,'#6a4939');else arc(0,17,5,.2,2.8,'#8b5c42',2);poly([[-4,-36],[-9,-48],[7,-44]],'#77563e');ctx.restore();
 if(game.phase==='pat'&&game.hit>0){ctx.globalAlpha=game.hit;arc(bum.x+26,bum.y+9,23,-.5,1.3,'#e5ce8e',2);arc(bum.x+26,bum.y+9,30,-.4,1.2,'#d6c487',1);ctx.globalAlpha=1}
 if(game.phase==='settle'&&game.hit>0){ctx.globalAlpha=game.hit;ellipse(x+38,y+80,19,14,'#dfb38e');arc(x+37,y+80,27,-.6,.6,'#e4cf96',2);ctx.globalAlpha=1}
 if(game.phase==='leg'||game.phase==='head'){const leg=game.phase==='leg',point=leg?bum:head,sign=leg?1:-1;ctx.globalAlpha=handInfo(game).open?.9:.22;line(point.x+sign*12,point.y+32,point.x+sign*57,point.y+32,'#e0d79d',3);poly([[point.x+sign*64,point.y+32],[point.x+sign*52,point.y+25],[point.x+sign*52,point.y+39]],'#e0d79d');ctx.globalAlpha=1}
 if(game.phase==='sleeping'){label('z',x+53,y-15,19,'#c9c99f');label('z',x+66,y-33,12,'#a3b494')}
}
function lighting(){const target=game.phase==='awake'?.1:clamp(game.sleep/100*.35+.08,.08,.43);light+=(target-light)*.025;ctx.fillStyle=`rgba(6,12,23,${light})`;ctx.fillRect(0,0,W,H);const g=ctx.createRadialGradient(195,290,30,195,290,180);g.addColorStop(0,'rgba(245,209,143,.08)');g.addColorStop(1,'rgba(245,209,143,0)');ctx.fillStyle=g;ctx.fillRect(0,80,W,440)}
function hud(){const p=game.phase;if(p==='sleeping'){mom();label(timeFormat(game.rest),195,65,25,'#d9d7b0')}else if(p==='rock'||RHYTHM[p]){for(let i=0;i<7;i++)round(159+i*11,51,6,3,2,i<game.progress*7?'#d9c58e':'#3b4848');}else if(p==='lower'){const v=clamp(game.balance,-1,1),good=Math.abs(v)<.19;round(154,29,82,48,12,null,good?'#a5c497':'#8c8d7a');line(165,53,225,53,'#697d71',1);ellipse(195+v*29,53,5,5,good?'#dbdfa5':'#dfaa75');arc(195,53,12,0,Math.PI*2,'#566d60',1);round(159,87,72,3,2,'#344847');round(159,87,72*game.lower,3,2,'#b7bf89')}else if(p==='leg'||p==='head'){const hi=handInfo(game),b=(Math.sin(game.phaseTime*2*Math.PI/3.8)+1)/2;arc(195,55,15+b*10,0,Math.PI*2,hi.open?'#f1dfa0':'#8b9379',hi.open?4:2);label(hi.open?'抽':isInhale(game)?'吸':'呼',195,60,11,'#e0dec0');round(159,91,72,4,2,'#344847');round(159,91,72*game[p],4,2,'#b7bf89');}
 if(game.arousal>25&&p!=='awake'&&p!=='sleeping')arc(345,49,10,-Math.PI/2,-Math.PI/2+game.arousal/100*Math.PI*2,'#d5a078',2);
}
function warnings(){for(const e of game.events){if(e.status==='warning'){ctx.globalAlpha=.3+.15*Math.sin(game.time*8);ellipse(e.x,e.y,e.w*.68,e.h*.65,'#d9b66b');ctx.globalAlpha=1;arc(e.x,e.y,Math.max(29,Math.max(e.w,e.h)*.42),-Math.PI/2,-Math.PI/2+Math.PI*2*clamp(e.left/e.lead,0,1),'#f1d28a',3);label('!',e.x,e.y+e.h*.54+13,16,'#f4db9b')}else label('✓',e.x,e.y-10,25,'#b7d3a3')}}
function draw(){ctx.clearRect(0,0,W,H);room();ctx.save();if(['rock','pat','awake'].includes(game.phase))ctx.globalAlpha=.5;props();bed();ctx.restore();baby();lighting();hud();warnings();drawRhythm()}
function drawRhythm(){const width=track.clientWidth||390;tc.clearRect(0,0,width,112);if(game.phase==='rock'){drawCradleTrack(width);return;}if(!RHYTHM[game.phase])return;const ri=rhythmInfo(game),target=width*.845,y=48,travel=2.35,beat=game.phaseTime/ri.period;tc.strokeStyle='#4c5d50';tc.lineWidth=2;tc.beginPath();tc.moveTo(13,y);tc.lineTo(width-13,y);tc.stroke();tc.strokeStyle='#a2b38a';tc.beginPath();tc.moveTo(target,y-30);tc.lineTo(target,y+30);tc.stroke();const pulse=Math.pow(Math.max(0,1-ri.distance/.22),2);tc.fillStyle=`rgba(196,213,145,${.06+pulse*.14})`;tc.beginPath();tc.arc(target,y,35+pulse*3,0,Math.PI*2);tc.fill();tc.strokeStyle=tapGlow>0?(tapResult==='miss'||tapResult==='spam'?'#bd8b6d':'#edf1bd'):'#c9c999';tc.lineWidth=tapGlow>0?3:1.5;tc.beginPath();tc.arc(target,y,30,0,Math.PI*2);tc.stroke();for(let i=Math.floor(beat)-1;i<=Math.ceil(beat+travel);i++){const offset=i-beat,x=target-offset*width*.349;if(x<8||x>width-8)continue;tc.globalAlpha=offset<-.23?Math.max(0,1+(offset+.23)*3):1;tc.fillStyle=Math.abs(offset)*ri.period<.2?'#ece4b7':'#829d86';tc.beginPath();tc.arc(x,y,Math.abs(offset)*ri.period<.2?10:7,0,Math.PI*2);tc.fill();tc.globalAlpha=1}tc.fillStyle='#8a9b8b';tc.font='10px -apple-system, sans-serif';tc.textAlign='left';if(game.progress<.35)tc.fillText('圆点碰环 · 轻点',16,89);else{tc.fillStyle='#b4c296';tc.fillText(game.phase==='rock'?'≈':'·  ·  ·',16,88)}if(tapGlow>0&&['perfect','good'].includes(tapResult)){tc.globalAlpha=tapGlow*2;tc.strokeStyle='#d2ddb1';tc.beginPath();tc.arc(target,y,32+(1-tapGlow*2)*16,0,Math.PI*2);tc.stroke();tc.globalAlpha=1}}

function drawCradleTrack(width){const r=rockInfo(game),cx=width/2,cy=5,rx=Math.min(135,width*.36),base=87;tc.strokeStyle='#61735f';tc.lineWidth=2;tc.beginPath();tc.moveTo(cx-rx,30);tc.quadraticCurveTo(cx,base+45,cx+rx,30);tc.stroke();[-1,1].forEach(side=>{tc.beginPath();tc.arc(cx+side*rx,30,13,0,Math.PI*2);tc.fillStyle=(r.canTap&&(r.side==='right'?1:-1)===side)?'#bfcf95':'#354b43';tc.fill();tc.strokeStyle='#bdc899';tc.stroke()});const u=clamp(r.angle/Math.max(r.amplitude,.001),-1,1),x=cx+u*rx,y=30+(1-u*u)*57;tc.beginPath();tc.arc(x,y,9,0,Math.PI*2);tc.fillStyle=r.pending?'#fff2b8':'#d5bd83';tc.fill();tc.fillStyle='#b8c8a2';tc.font='11px sans-serif';tc.textAlign='center';tc.fillText(r.pending?'接住了':r.canTap?'现在轻点':'等它到左右顶点',cx,17);}

let uiTime=0,rafId=0;
function frame(ts){const dt=last?Math.min(.05,(ts-last)/1000):1/60;last=ts;if(playing&&!paused&&!document.hidden){timer.sample();const arrow=(keys.has('ArrowRight')?1:0)-(keys.has('ArrowLeft')?1:0);const hi=handInfo(game);if(keys.size){input.down=keys.has(' ')||arrow!==0;input.dx=(hi?(arrow|| (keys.has(' ')?hi.direction:0))*(game.phase==='leg'?80:65):arrow*38)*dt;if(game.phase==='lower')touchBalance=clamp(touchBalance+arrow*.65*dt,-1,1);}else if(input.down&&input.auto&&!input.dragged&&hi){input.dx=hi.direction*(game.phase==='leg'?80:65)*dt;}input.vx=input.dx/dt;step(game,{...input,balance:touchBalance},dt);input.dx=0;tapGlow=Math.max(0,tapGlow-dt);audio.update(game,dt);if(game.phase==='sleeping'&&!completedRun)finishTiming();uiTime+=dt;if(uiTime>.05||game.phase!==lastPhase||game.complete){updateUI();uiTime=0}}draw();if(!document.hidden)rafId=requestAnimationFrame(frame);else rafId=0}
document.addEventListener('visibilitychange',()=>{if(document.hidden){if(rafId)cancelAnimationFrame(rafId);rafId=0;}else if(!rafId){last=0;rafId=requestAnimationFrame(frame)}});updateUI();rafId=requestAnimationFrame(frame);$('start').disabled=false;$('boot-status').textContent='';
